package com.snovasys.ledgerline.dto;

import java.time.LocalDateTime;

/**
 * Report generated by verifying the cryptographic tamper-evident hash chain of all audit logs.
 */
public class AuditChainIntegrityReport {

    private boolean chainValid;
    private long totalRecordsVerified;
    private Long tamperedRecordId;
    private String failureReason;
    private LocalDateTime verifiedAt;

    public AuditChainIntegrityReport() {
        this.verifiedAt = LocalDateTime.now();
    }

    public AuditChainIntegrityReport(boolean chainValid, long totalRecordsVerified,
                                     Long tamperedRecordId, String failureReason) {
        this.chainValid = chainValid;
        this.totalRecordsVerified = totalRecordsVerified;
        this.tamperedRecordId = tamperedRecordId;
        this.failureReason = failureReason;
        this.verifiedAt = LocalDateTime.now();
    }

    // Getters and Setters
    public boolean isChainValid() {
        return chainValid;
    }

    public void setChainValid(boolean chainValid) {
        this.chainValid = chainValid;
    }

    public long getTotalRecordsVerified() {
        return totalRecordsVerified;
    }

    public void setTotalRecordsVerified(long totalRecordsVerified) {
        this.totalRecordsVerified = totalRecordsVerified;
    }

    public Long getTamperedRecordId() {
        return tamperedRecordId;
    }

    public void setTamperedRecordId(Long tamperedRecordId) {
        this.tamperedRecordId = tamperedRecordId;
    }

    public String getFailureReason() {
        return failureReason;
    }

    public void setFailureReason(String failureReason) {
        this.failureReason = failureReason;
    }

    public LocalDateTime getVerifiedAt() {
        return verifiedAt;
    }

    public void setVerifiedAt(LocalDateTime verifiedAt) {
        this.verifiedAt = verifiedAt;
    }
}

